#Operators only ever start a check from an enabled, Released check sheet - never a Draft or In Revision one.
#Auto check sheets are filled in from their tags, so they're left out unless Include Auto Checks is ticked (read live: a struct binding can run with stale inputs)
filters = {'chkShtVersionStateNameList': ['Released'], 'enabled': True}
if not self.view.custom.includeAuto: filters['auto'] = False
return system.kanoa.quality.sheet.getSheets(filters)
